"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   committeeMembers: () => (/* binding */ committeeMembers),\n/* harmony export */   getCommitteeMember: () => (/* binding */ getCommitteeMember)\n/* harmony export */ });\nconst committeeMembers = [\n    {\n        slug: \"trustee\",\n        name: \"Shri. Megeshyam Dattaram Khedekar\",\n        role: \"Trustee\",\n        marathiRole: \"विश्वस्त\",\n        marathiName: \"श्री. मेगाश्याम दत्ताराम खेडेकर\",\n        initials: \"01\",\n        image: \"/trustee.jpeg\",\n        institution: \"Aai Ramai Devi Social Institution, Ghonse\",\n        paragraphs: [\n            \"Aai Ramai Devi Social Institution, Ghonse, is the result of the collective thoughts, unity and cooperation of all of us who have come together with the vision of bringing about the social, educational and overall development of our village. Started in the sacred name of Gramdevata Aai Ramai Devi, it is our heartfelt desire that this institution should become a strong platform that supports the weaker and underprivileged sections of society while ensuring that every individual in the village gets an opportunity to participate in the process of development.\",\n            \"As a Trustee, I firmly believe that the foundation of this institution must rest on four fundamental values—trust, transparency, honesty and social responsibility. It is our collective responsibility to ensure that every donation and contribution received by the institution is utilised properly, responsibly and transparently, so that the maximum possible benefit reaches society.\",\n            \"Through this institution, we will make sincere efforts to undertake long-term, sustainable and meaningful work in various fields such as education, healthcare, sports, women and child development, environmental conservation, agriculture, preservation of cultural heritage and social service.\",\n            \"This institution has been established in the name of our revered Gramdevata, Aai Ramai Devi. Therefore, every office-bearer and member is expected to discharge their responsibilities selflessly, honestly and with a spirit of service. The interests, objectives and social responsibilities of the institution must always be given priority over personal differences and individual interests.\",\n            \"Today, we are laying the foundation stone of this institution; however, tomorrow, our work should create a capable, transparent and exemplary social platform for the generations to come. My sincere resolve is that the institution we are building today should not remain limited to our generation, but should become a valuable social legacy for future generations.\",\n            \"With the blessings of Aai Ramai Devi, the cooperation of everyone and our collective unity, may this institution continue to work with dedication for the welfare of society and make a meaningful contribution to the development of Ghonse village. This is my heartfelt prayer and sincere resolve.\"\n        ]\n    },\n    {\n        slug: \"president\",\n        name: \"Shri. Santosh Waman Kate\",\n        role: \"President\",\n        marathiRole: \"अध्यक्ष\",\n        marathiName: \"श्री. संतोष वामन काते\",\n        initials: \"02\",\n        image: \"/President.jpeg\",\n        institution: \"Aai Ramai Educational and Social Institution\",\n        paragraphs: [\n            \"Aai Ramai Educational and Social Institution has been established with the vision of contributing to the development of our village and promoting the overall progress and welfare of every section of society. Our institution is committed to bringing together the citizens of our village and working collectively in various fields such as social welfare, education, healthcare, sports, culture, environmental conservation, and the development of women and children.\",\n            \"This institution does not belong to any individual or to a select few. It is an institution of the entire village and for the entire village. Our primary objective is to ensure that assistance reaches every deserving person through the institution, to provide proper educational encouragement and guidance to the youth, and to undertake constructive initiatives for the overall development of the village.\",\n            \"Transparency, trust, discipline, and a proper decision-making process are of utmost importance in every activity undertaken by the institution. A position within the institution is not merely a matter of honour or recognition; it carries with it a responsibility. We expect every office-bearer and member to perform their duties with this sense of responsibility and commitment.\",\n            \"The institution cannot function successfully without the cooperation and support of all. Therefore, with the trust and participation of the senior citizens, the enthusiasm of the youth, women, students, and every villager, let us work together to make this institution stronger, more effective, and an exemplary organisation.\",\n            \"With the blessings of Aai Ramai Devi, our firm resolve is to contribute to the development of the village by working selflessly, continuously, and with dedication. Through collective efforts and unity, we aspire to create meaningful and lasting progress for our community.\",\n            \"For the institution to grow, the society it serves must grow through the institution.\"\n        ]\n    },\n    {\n        slug: \"secretary\",\n        name: \"Shri. Sagar Keshav Khedekar\",\n        role: \"Secretary\",\n        marathiRole: \"सचिव\",\n        initials: \"03\",\n        image: \"/secretary.jpeg\",\n        paragraphs: [\n            \"Aai Ramai Social Institution, Ghonse, is a symbol of our unity, service, and social responsibility. Keeping in mind the needs and concerns of every family, youth, woman, student, and senior citizen in our village, we have collectively envisioned working towards the overall development and welfare of our community.\",\n            \"As the Secretary, my role is not limited merely to overseeing the administrative functioning of the institution. My responsibility is to ensure proper coordination among all office-bearers and members so that the institution’s objectives, policies, plans, and every initiative are implemented effectively and in an organised manner.\",\n            \"Special emphasis will be placed on transparency, discipline, responsibility, and proper time management in all the activities of the institution. We are committed to maintaining proper records of every decision taken by the institution, planning and documenting various activities, preparing reports, and ensuring that accurate and relevant information reaches all members of the institution in a timely manner.\",\n            \"Through our institution, we aim to undertake concrete and long-term initiatives in the fields of education, healthcare, sports, women and child development, environmental conservation, agriculture, culture, and social service.\",\n            \"In my opinion, the true strength of an institution does not lie merely in its office-bearers, but in every member who is sincerely and faithfully connected with the institution and its vision. Therefore, let us all set aside our individual differences and work together with unity and dedication towards achieving the objectives of the institution.\",\n            \"With the blessings of Aai Ramai Devi and the cooperation of everyone, I am fully confident that this institution will remain dedicated to the welfare and development of our village and, through its work, establish itself as an exemplary social institution in the district.\"\n        ]\n    },\n    {\n        slug: \"treasurer\",\n        name: \"Shri. Tejas Dipak Darge\",\n        role: \"Treasurer\",\n        marathiRole: \"खजिनदार\",\n        marathiName: \"श्री. तेजस दीपक दर्गे\",\n        initials: \"04\",\n        image: \"/treasurer.jpeg\",\n        institution: \"Aai Ramai Social and Educational Institution\",\n        paragraphs: [\n            \"As the Treasurer, I would like to express my views regarding the financial, educational, and welfare-related activities of the institution.\",\n            \"Aai Ramai Social and Educational Institution has been established with the objective of working towards the development of the weaker and underprivileged sections of society, as well as in the areas of education, healthcare, women’s welfare, and social awareness. Through the institution, we intend to undertake various social and educational initiatives for the overall development and welfare of the community.\",\n            \"As the Treasurer, it will be my primary responsibility to maintain transparency, honesty, and accountability in all financial transactions of the institution. I will always make sincere efforts to ensure that all financial dealings are conducted properly and transparently, in accordance with the objectives of the institution and all applicable rules and regulations.\",\n            \"With the cooperation and support of all office-bearers, members, and well-wishers of the institution, I am fully confident that we will successfully achieve our objective of serving and upholding the values of Aai Ramai Devi and working towards the progress and welfare of society.\",\n            \"With transparency in our actions, honesty in our intentions, and unity in our efforts, we can build an institution that truly serves society.\"\n        ]\n    }\n];\nfunction getCommitteeMember(slug) {\n    return committeeMembers.find((member)=>member.slug === slug);\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/committeeMembers.js\n");

